const dictionary = new Map(translations);
const substitutions = [...dictionary].filter(([zh]) => (zh.match(/[\u3400-\u9fff]/gu)||[]).length>=2).sort((a,b) => b[0].length-a[0].length);
const originals = new WeakMap();
const originalAttributes = new WeakMap();
let language = (() => { try { return localStorage.getItem('watering-language') === 'en' ? 'en' : 'zh'; } catch { return 'zh'; } })();
export const getLanguage = () => language;
export function translateText(value) {
  if (language !== 'en' || !/[\u3400-\u9fff]/u.test(value)) return value;
  const trimmed = value.trim();
  if (dictionary.has(trimmed)) return value.replace(trimmed,dictionary.get(trimmed));
  const patterns=[
    [/^第\s*(\d+)\s*\/\s*(\d+)\s*页$/u,'Page $1 of $2'],
    [/^共\s*(\d+)\s*条记录$/u,'$1 records total'],
    [/^浇水\s*(\d+)\s*次记录$/u,'$1 watering records'],
    [/^降雨\s*(\d+)\s*次记录$/u,'$1 rain records'],
    [/^已读取\s*(\d+)\s*条设备事件$/u,'Read $1 device events'],
    [/^已读取\s*(\d+)\s*条近期记录$/u,'Read $1 recent records'],
  ];
  for(const [pattern,replacement] of patterns)if(pattern.test(trimmed))return value.replace(trimmed,trimmed.replace(pattern,replacement));
  let result=value;
  for (const [zh,en] of substitutions) if (result.includes(zh)) result=result.replaceAll(zh,en);
  result=result.replace(/(\d+)\s*次/gu,'$1 times').replace(/(\d+)\s*小时/gu,'$1 hours').replace(/(\d+)\s*分钟/gu,'$1 minutes').replace(/(\d+)\s*天/gu,'$1 days');
  result=result.replace(/(Less than 1 minute|\d+ (?:minutes|hours|days))前/gu,'$1 ago');
  return result;
}
export function setLanguage(next) {
  language=next === 'en' ? 'en' : 'zh';
  document.documentElement.lang=language === 'en' ? 'en' : 'zh-CN';
  document.documentElement.dataset.language=language;
  try { localStorage.setItem('watering-language',language); } catch {}
  const button=document.querySelector('#language-toggle');
  if(button){button.textContent=language === 'en'?'中文':'EN';button.lang=language === 'en'?'zh-CN':'en';button.setAttribute('aria-label',language === 'en'?'Switch to Chinese':'切换为英语');}
}
function translateNode(node) {
  if(node.nodeType===Node.TEXT_NODE){
    if(node.parentElement?.closest('script,style,pre,code,[translate="no"],#language-toggle'))return;
    const current=node.nodeValue;
    if(language==='zh'){const original=originals.get(node);if(original!=null&&current!==original)node.nodeValue=original;return;}
    if(!/[\u3400-\u9fff]/u.test(current))return;
    const next=translateText(current);if(next!==current){originals.set(node,current);node.nodeValue=next;}
    return;
  }
  if(node.nodeType!==Node.ELEMENT_NODE&&node.nodeType!==Node.DOCUMENT_NODE)return;
  const element=node.nodeType===Node.ELEMENT_NODE?node:null;
  if(element?.matches('script,style,pre,code,[translate="no"],#language-toggle'))return;
  if(element)for(const name of ['aria-label','placeholder','title','alt']){
    const value=element.getAttribute(name);if(value==null)continue;
    const saved=originalAttributes.get(element)?.[name];
    if(language==='zh'){if(saved!=null&&value!==saved)element.setAttribute(name,saved);continue;}
    if(!/[\u3400-\u9fff]/u.test(value))continue;
    const next=translateText(value);if(next!==value){const record=originalAttributes.get(element)||{};record[name]=value;originalAttributes.set(element,record);element.setAttribute(name,next);}
  }
  for(const child of node.childNodes)translateNode(child);
}
export function localize(root=document){translateNode(root);if(language==='en')document.title=translateText(document.title);}
export function observeLanguage(){
  const observer=new MutationObserver(records=>{
    if(language!=='en')return;
    for(const record of records){
      if(record.type==='childList')for(const node of record.addedNodes)translateNode(node);
      else if(record.type==='characterData')translateNode(record.target);
      else if(record.type==='attributes')translateNode(record.target);
    }
  });
  observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title','alt']});
  return observer;
}
setLanguage(language);
